{
  "items": [
    {
      "title": "Eurostat – Government Revenue, Expenditure and Main Aggregates (gov_10a_main)",
      "url_or_doi": "https://doi.org/10.2908/gov_10a_main",
      "justification": "A comprehensive official European dataset covering Germany's annual government revenue, expenditure, fiscal balances, taxes, social contributions, subsidies and other fiscal indicators. Includes data from 2020 to 2025, with historical observations extending to 1975. Particularly useful for examining German fiscal policy, government spending trends, and the economic consequences of the COVID-19 pandemic."
    },
    {
      "title": "Eurostat – General Government Expenditure by Function (COFOG)",
      "url_or_doi": "https://doi.org/10.2908/gov_10a_exp",
      "justification": "Provides detailed annual government expenditure data classified by policy function, including education, healthcare, defense, social protection, infrastructure, environmental protection and economic affairs. Covers Germany during 2020–2025, with earlier historical data. Especially valuable for analyzing how German public spending priorities changed throughout the 2020s."
    },
    {
      "title": "Eurostat – Quarterly Non-Financial Accounts for General Government",
      "url_or_doi": "https://doi.org/10.2908/gov_10q_ggnfa",
      "justification": "Contains quarterly statistics on government revenue, expenditure, taxation, social transfers and fiscal deficits or surpluses. Allows researchers to examine short-term developments in Germany's public finances during the 2020s. Particularly relevant for studying fiscal responses to COVID-19, inflation, energy price shocks and changes in economic policy."
    },
    {
      "title": "Eurostat – Government Deficit/Surplus, Debt and Associated Data",
      "url_or_doi": "https://doi.org/10.2908/gov_10dd_edpt1",
      "justification": "Official European government finance dataset providing annual statistics on public debt, government deficits and surpluses, and related fiscal indicators. Includes Germany and supports analysis of fiscal sustainability, public borrowing, debt management and compliance with European fiscal rules during the 2020s."
    },
    {
      "title": "German Federal Statistical Office (Destatis) – National Accounts: Government Revenue, Expenditure and Fiscal Balance",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/statistic/81000/table/81000-0031/search/s/ODEwMDA%3D",
      "justification": "Official German national accounts dataset containing annual government revenue, expenditure and fiscal balance statistics. Includes observations for 2020–2025. Particularly useful for studying changes in Germany's fiscal position, the relationship between government income and expenditure, and the effects of major economic policy interventions."
    },
    {
      "title": "German Federal Statistical Office (Destatis) – Tax Revenue by Tax Type",
      "url_or_doi": "https://genesis.destatis.de/datenbank/online/url/ccfa4350",
      "justification": "Provides annual German tax revenue statistics disaggregated by tax category, including observations from 2020 through 2025. Useful for investigating the composition of public revenue, changes in taxation, and the effects of economic developments on government tax receipts. Particularly relevant to research on fiscal capacity and the financing of public expenditure."
    },
    {
      "title": "Deutsche Bundesbank – Public Finances Statistics",
      "url_or_doi": "https://www.bundesbank.de/en/statistics/public-finances",
      "justification": "Official Bundesbank statistical resource providing time-series data on Germany's public finances. Covers government revenue, expenditure, fiscal deficits, public debt and other fiscal indicators. Includes national accounts measures and budget-based financial statistics. Particularly valuable for examining fiscal policy developments during the 2020s and comparing different measures of government finances."
    },
    {
      "title": "German Federal Statistical Office (Destatis) – Expenditure, Revenue and Financial Balance of Public Budgets",
      "url_or_doi": "https://www.destatis.de/EN/Themes/Government/Public-Finance/Expenditure-Revenue-And-Financial-Balance-Of-Public-Budgets/_node.html",
      "justification": "Official German statistical resource covering public budget revenue, expenditure and financial balances. Provides access to information about government finances at different administrative levels, including federal, state and municipal budgets. Particularly relevant for analyzing public expenditure trends, fiscal decentralization and budget deficits in Germany during the 2020s."
    },
    {
      "title": "Eurostat – Quarterly Financial Accounts for General Government",
      "url_or_doi": "https://doi.org/10.2908/gov_10q_ggfa",
      "justification": "Provides quarterly financial accounts for government, including financial assets, liabilities, financial transactions and government financial positions. Covers Germany throughout the 2020s, with observations extending into 2026. Useful for examining government financing, debt accumulation, changes in public sector financial assets and the financial implications of fiscal policy."
    },
    {
      "title": "Eurostat – General Government Expenditure by Function: Social Protection, Health and Education",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/product/view/tepsr_sp110",
      "justification": "A focused dataset reporting government expenditure on social protection, healthcare and education as a percentage of GDP. Includes annual observations for Germany from 2020 to 2025. Particularly useful for examining welfare spending, social policy priorities and changes in the allocation of public resources following the COVID-19 pandemic."
    },
    {
      "title": "Eurostat – Total General Government Expenditure",
      "url_or_doi": "https://ec.europa.eu/eurostat/databrowser/view/tec00023/default/bar?lang=en",
      "justification": "Provides standardized government expenditure indicators suitable for comparing Germany with other European countries. Particularly useful for analyzing changes in the overall scale of public spending relative to economic activity during the 2020s. Supports research into fiscal expansion, expenditure restraint and cross-country differences in government economic intervention."
    },
    {
      "title": "OECD – OECD Data Explorer",
      "url_or_doi": "https://www.oecd.org/en/data/datasets/oecd-DE.html",
      "justification": "Official OECD statistical platform providing access to internationally comparable economic and public finance datasets. Researchers can locate indicators covering government revenue, taxation, public expenditure, fiscal balances and debt for Germany during the 2020s. Particularly useful for comparative research evaluating Germany's economic and fiscal policies relative to other OECD economies. This is a dataset discovery platform rather than an individual dataset."
    }
  ]
}
